import 'package:flutter/material.dart';import 'package:intl/intl.dart';import 'package:shamsi_date/shamsi_date.dart';import '../database/db_helper.dart';import '../models/study_session.dart';
class HistoryScreen extends StatefulWidget{const HistoryScreen({super.key});@override State<HistoryScreen> createState()=>_HistoryScreenState();}
class _HistoryScreenState extends State<HistoryScreen>{List<StudySession> data=[];@override void initState(){super.initState();load();}Future<void>load()async{data=await DbHelper.instance.getSessions();if(mounted)setState((){});}String jalali(DateTime d){final j=Jalali.fromDateTime(d);return '${j.year}/${j.month.toString().padLeft(2,'0')}/${j.day.toString().padLeft(2,'0')}';}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تاریخچهٔ مطالعه')),body:data.isEmpty?const Center(child:Text('نشستی ثبت نشده است.')):ListView.builder(itemCount:data.length,itemBuilder:(c,i){final s=data[i];return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:4),child:ListTile(leading:const Icon(Icons.menu_book),title:Text(s.bookTitle??'مطالعه'),subtitle:Text('${jalali(s.startAt)} • ${DateFormat('HH:mm:ss').format(s.startAt)} – ${DateFormat('HH:mm:ss').format(s.endAt)}'),trailing:Text('${s.durationSeconds~/60} دقیقه')));}));}}
